window.MG_LAZY_DATA["data/lazy/resources/comm-v28-109-7ea5a5ad0e5463e8.json"]={sha256:"7ea5a5ad0e5463e8034095196a63e88bd6cb591e0e3fc36639dad8abf6f09cae",value:{"sources":[{"id":"v28-case-de6985cc71510c51","url":"https://www.cisco.com/c/en/us/products/collateral/networking/wireless/wifi7-future-of-wireless-dg.html","title":"Wi-Fi 7 and the Growing Future of Wireless Design Guide","titleEn":"Wi-Fi 7 and the Growing Future of Wireless Design Guide","publisher":"Cisco","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"media":{"courses":[{"courseId":"comm-v28-109","videos":[],"guides":[]}]},"related":{"courses":[{"courseId":"comm-v28-109","related":[{"id":"comm-v28-110","referenceUrls":["https://www.ieee802.org/11/"],"title":"企業 Wi-Fi Roaming：掃描、驗證與切換時間","titleEn":"Enterprise Wi-Fi roaming: scan, authentication and transition timing","why":"用兩課的可觀察驗收條件比較模型邊界：交付物能重現 280 Mbit/s ideal 與 200 Mbit/s ideal，保留失敗情境且每個通過判定有明確門檻；需分開列出模型未涵蓋的實際系統驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: The artifacts must reproduce 280 Mbit/s ideal and 200 Mbit/s ideal, preserve failing scenarios and attach a threshold to each pass decision; list actual-system validation outside this model separately.","difference":"能推導並解釋80 ms與45 ms，建立roam_events.csv、分段中斷表、裝置能力證據，並完成以下驗收：50 ms中斷預算僅快切換例通過；記錄裝置支援與安全模式，不能承諾所有手機同結果。","differenceEn":"Derive and explain 80 ms and 45 ms; create roam_events.csv, phase-delay table and client-capability evidence; apply this acceptance decision: Only the fast example fits50 ms; record client support and security mode rather than promising identical behavior on all phones.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["從原理 頻寬穿孔排除受干擾區段；合法模式與主要通道限制仍需標準檢查，剩餘頻寬不是無條件可用。 展開基準式 (160-20)*2；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：以位元遮罩逐塊計數7與5，驗證排除區未再分配；另外保留合法穿孔模式查核。 將兩條推導一起存入 puncture_mask.csv、有效頻寬表、模式一致性。","從原理 漫遊中斷由掃描、驗證與重新關聯等串接步驟構成；快切換只能縮短其中部分。 展開基準式 30+40+10；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：以事件名稱與單調時間戳量測每段；最後舊AP封包到新AP首包需涵蓋全部空隙。 將兩條推導一起存入 roam_events.csv、分段中斷表、裝置能力證據。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Starting from Puncturing excludes interfered subbands; legal patterns and primary-channel constraints still apply, so residual bandwidth is not automatically usable., expand baseline expression (160-20)*2; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Count seven/five active blocks from a bitmask, ensure excluded blocks are not scheduled, and separately validate legal puncturing patterns. Save both derivations with puncture_mask.csv, usable-bandwidth table and mask consistency.","Starting from Roaming interruption includes scanning, authentication and reassociation; fast transition only shortens some components., expand baseline expression 30+40+10; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Measure named phases with monotonic timestamps; last-old-AP to first-new-AP timing must include all gaps. Save both derivations with roam_events.csv, phase-delay table and client-capability evidence.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]},{"id":"comm-v28-119","referenceUrls":["https://resources.lora-alliance.org/document/rp002-1-0-5-lorawan-regional-parameters"],"title":"LoRaWAN 空中時間：區域限制與報告配額","titleEn":"LoRaWAN airtime: regional limits and report budgets","why":"用兩課的可觀察驗收條件比較模型邊界：交付物能重現 280 Mbit/s ideal 與 200 Mbit/s ideal，保留失敗情境且每個通過判定有明確門檻；需分開列出模型未涵蓋的實際系統驗證。","whyEn":"Compare model boundaries using observable acceptance criteria: The artifacts must reproduce 280 Mbit/s ideal and 200 Mbit/s ideal, preserve failing scenarios and attach a threshold to each pass decision; list actual-system validation outside this model separately.","difference":"能推導並解釋180 reports/hour與45 reports/hour，建立lorawan_airtime.csv、區域版本欄、含重試排程，並完成以下驗收：每分鐘1報共60報需求只在0.2 s例可行；真實部署須依當地核准參數重算。","differenceEn":"Derive and explain 180 reports/hour and 45 reports/hour; create lorawan_airtime.csv, regional-version field and retry-inclusive schedule; apply this acceptance decision: Sixty hourly reports fit only the0.2 s case; real deployments require recalculation with locally authorized parameters.","transfer":"保留單位與邊界條件，僅轉移可證明相容的驗證方法。","transferEn":"Retain units and boundary conditions; transfer only demonstrably compatible verification methods.","practice":["從原理 頻寬穿孔排除受干擾區段；合法模式與主要通道限制仍需標準檢查，剩餘頻寬不是無條件可用。 展開基準式 (160-20)*2；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：以位元遮罩逐塊計數7與5，驗證排除區未再分配；另外保留合法穿孔模式查核。 將兩條推導一起存入 puncture_mask.csv、有效頻寬表、模式一致性。","從原理 給定空中時間預算時，報告數上限為floor(可用時間/每包時間)；區域法規與通道群必須另核實。 展開基準式 floor(3600*0.01/0.2)；逐步記錄中間量與單位，先手算再用計算器或Python重算。接著用不同表示法交叉檢查：建立3600 s排程、逐筆累加空中時間；重傳與join也占預算，不能只算成功應用報告。 將兩條推導一起存入 lorawan_airtime.csv、區域版本欄、含重試排程。","比較兩個模型的輸入、誤差與驗收條件，記錄不能沿用的假設。"],"practiceEn":["Starting from Puncturing excludes interfered subbands; legal patterns and primary-channel constraints still apply, so residual bandwidth is not automatically usable., expand baseline expression (160-20)*2; record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Count seven/five active blocks from a bitmask, ensure excluded blocks are not scheduled, and separately validate legal puncturing patterns. Save both derivations with puncture_mask.csv, usable-bandwidth table and mask consistency.","Starting from With a stated airtime budget, packet count isfloor(available time/airtime per packet); regional rules and subband aggregation require separate verification., expand baseline expression floor(3600*0.01/0.2); record intermediate values and units, calculate manually, then repeat with a calculator or Python. Use this independent representation: Build a3600 s schedule and sum airtime; retries and joins consume budget as well as successful reports. Save both derivations with lorawan_airtime.csv, regional-version field and retry-inclusive schedule.","Compare inputs, errors, and criteria; document assumptions that cannot be transferred."]}],"references":[{"id":"v28-case-e022e0677b1fd8a0","url":"https://www.ieee802.org/11/","title":"IEEE 802.11 Wireless LAN standards working group","titleEn":"IEEE 802.11 Wireless LAN standards working group","publisher":"IEEE 802.11 Working Group","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."},{"id":"v28-case-08de258a253335ea","url":"https://resources.lora-alliance.org/document/rp002-1-0-5-lorawan-regional-parameters","title":"RP002-1.0.5 LoRaWAN Regional Parameters","titleEn":"RP002-1.0.5 LoRaWAN Regional Parameters","publisher":"LoRa Alliance","scope":"查證具名案例與原理背景。課內數值、故障資料與判準為原創教學假設；請勿當作廠商規格或操作程序。","scopeEn":"Establish named case and principle context. Numbers, fault data, and criteria are original teaching assumptions, not manufacturer specifications or operating procedures."}],"overview":"比較相鄰案例與另一組案例的模型、可量測結果及可轉移的驗證方法。","overviewEn":"Compare neighboring and cross-group cases by model, measurable outcome, and transferable verification method."}]},"places":{"courses":[]},"vendors":{"courses":[],"vendors":[]}}};
